class BasicException(Exception):
    pass


class TimeoutException(BasicException):
    pass


class NcPidNotFoundException(BasicException):
    pass


class UnexpectedCellsThroughputError(BasicException):
    def __init__(self,
                 msg,  # type: str
                 throughput=None,  # type: list
                 ):
        self.throughput = throughput
        super(UnexpectedCellsThroughputError, self).__init__(msg)


class ConnectionError(Exception):
    pass


class FileProtocolClientError(ConnectionError):
    pass
